from typing import Any


def format_table(headers: list[str], rows: list[list[Any]]) -> str:
    num_cols = len(headers)

    # Normalize rows to have the same number of columns as headers
    processed_rows = []
    for row in rows:
        padded_row = list(row)
        if len(padded_row) < num_cols:
            padded_row.extend([None] * (num_cols - len(padded_row)))
        elif len(padded_row) > num_cols:
            padded_row = padded_row[:num_cols]
        processed_rows.append(padded_row)

    # Format cell values into strings
    formatted_headers = [str(h) if h is not None else "" for h in headers]
    formatted_rows = []
    for row in processed_rows:
        formatted_row = []
        for cell in row:
            if cell is None:
                formatted_row.append("")
            elif isinstance(cell, float):
                formatted_row.append(f"{cell:.2f}")
            else:
                formatted_row.append(str(cell))
        formatted_rows.append(formatted_row)

    # Determine numeric columns
    # A column is numeric when every non-None cell in it is an int or float (bool does not count)
    # and it has at least one such cell.
    is_numeric = [False] * num_cols
    for col_idx in range(num_cols):
        has_numeric = False
        all_numeric_or_none = True

        # Check header? The prompt says "every non-None cell in it", usually headers are strings,
        # but let's check cells in the rows. Headers are strings so they wouldn't be int/float anyway,
        # meaning a column's numeric status is determined by its cells.
        for row in processed_rows:
            cell = row[col_idx]
            if cell is not None:
                if isinstance(cell, bool) or not isinstance(cell, (int, float)):
                    all_numeric_or_none = False
                    break
                else:
                    has_numeric = True

        if has_numeric and all_numeric_or_none:
            is_numeric[col_idx] = True

    # Calculate column widths
    col_widths = [len(h) for h in formatted_headers]
    for row in formatted_rows:
        for col_idx, cell_str in enumerate(row):
            if len(cell_str) > col_widths[col_idx]:
                col_widths[col_idx] = len(cell_str)

    # Build header line
    header_cells = []
    for col_idx, h_str in enumerate(formatted_headers):
        width = col_widths[col_idx]
        if is_numeric[col_idx]:
            header_cells.append(h_str.rjust(width))
        else:
            header_cells.append(h_str.ljust(width))
    header_line = " | ".join(header_cells)

    # Build separator line
    separator_cells = ["-" * width for width in col_widths]
    separator_line = "-+-".join(separator_cells)

    # Build data rows
    data_lines = []
    for row in formatted_rows:
        row_cells = []
        for col_idx, cell_str in enumerate(row):
            width = col_widths[col_idx]
            if is_numeric[col_idx]:
                row_cells.append(cell_str.rjust(width))
            else:
                row_cells.append(cell_str.ljust(width))
        data_lines.append(" | ".join(row_cells))

    # Combine all lines, strip trailing spaces from each, and join with "\n"
    all_lines = [header_line, separator_line] + data_lines
    stripped_lines = [line.rstrip() for line in all_lines]
    return "\n".join(stripped_lines)
